render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#stack-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

// Filtrar solo las pastillas que tengan texto escrito
const activePills = [];
for (let i = 1; i <= 8; i++) {
  const txt = params[`text_${i}`];
  if (txt && typeof txt === 'string' && txt.trim().length > 0) {
    activePills.push(txt.trim());
  }
}

const fallSpeed = params.fall_speed || 1.2;
const dropDelay = params.drop_delay || 0.45;
const pillW = params.pill_width || 340;
const pillH = params.pill_height || 50;
const pillCorner = params.pill_corner !== undefined ? params.pill_corner : 14;
const pillGap = params.pill_gap !== undefined ? params.pill_gap : 8;
const fontFamily = params.font_family || 'Segoe UI, sans-serif';
const fontSize = params.font_size || 18;

const pillBg = params.pill_color || '#182030';
const textColor = params.text_color || '#FFFFFF';
const borderColor = params.border_color || '#00E5FF';
const bgColor = params.bg_color || '#0B0E14';
const showGlow = params.show_glow !== false;
const loopAnim = params.loop_anim !== false;

// Fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

if (activePills.length === 0) return;

// Easing con rebote físico (Bounce Out)
function easeOutBounce(x) {
  const n1 = 7.5625;
  const d1 = 2.75;
  if (x < 1 / d1) {
    return n1 * x * x;
  } else if (x < 2 / d1) {
    return n1 * (x -= 1.5 / d1) * x + 0.75;
  } else if (x < 2.5 / d1) {
    return n1 * (x -= 2.25 / d1) * x + 0.9375;
  } else {
    return n1 * (x -= 2.625 / d1) * x + 0.984375;
  }
}

// Cálculo de tiempos de animación
const N = activePills.length;
const totalStackH = N * pillH + (N - 1) * pillGap;
const floorY = (height + totalStackH) / 2;
const dropDuration = 0.85 / fallSpeed;
const cycleDuration = N * dropDelay + dropDuration + 2.5;

let t = time;
if (loopAnim) {
  t = time % cycleDuration;
}

const cx = width / 2;

// Dibujar cada pastilla activa
for (let j = 0; j < N; j++) {
  const startT = j * dropDelay;

  if (t < startT) continue;

  const elapsed = t - startT;
  const rawProgress = Math.min(1, elapsed / dropDuration);
  const easedProgress = easeOutBounce(rawProgress);

  // Posición destino (j=0 es la base inferior)
  const targetY = floorY - (j + 1) * pillH - j * pillGap;
  const startY = -pillH - 80;

  const currentY = startY + (targetY - startY) * easedProgress;

  c.save();
  c.translate(cx - pillW / 2, currentY);

  // Brillo neón opcional
  if (showGlow) {
    c.shadowColor = borderColor;
    c.shadowBlur = 12;
  }

  // Cuerpo de la pastilla
  c.fillStyle = pillBg;
  c.strokeStyle = borderColor;
  c.lineWidth = 2;

  c.beginPath();
  c.roundRect(0, 0, pillW, pillH, pillCorner);
  c.fill();
  c.stroke();

  // Texto centrado
  c.shadowBlur = 0;
  c.fillStyle = textColor;
  c.font = `bold ${fontSize}px ${fontFamily}`;
  c.textAlign = 'center';
  c.textBaseline = 'middle';
  c.fillText(activePills[j], pillW / 2, pillH / 2);

  c.restore();
}
